a.receive(m1);            // self-delivery
b.receive(m1);            // delivers immediately (no deps)

const m2 = a.broadcast({ reply: 'hi' });   // deps = {m1}
a.receive(m2);
b.receive(m2);            // delivers after m2's deps are present

